        for x in range(64):
            if board[y][x] in (1, 2, 3, 14):
                # Every node has its central two cells on its top and bottom rows.
                if (x + 1 < 64 and y + 3 < 64 and x >= 1 and y >= 3
                        and board[y][x + 1] == board[y][x]
                        and board[y + 3][x] == board[y][x]
                        and board[y + 1][x - 1] == board[y][x]
                        and board[y + 1][x + 2] == board[y][x]):
                    result[(x, y + 3)] = board[y][x]
    return result


