        a, b = selected, p
        dx = (b[0] - a[0]) // 6
        dy = (b[1] - a[1]) // 6
        cur = a
        while True:
            _paint(board, cur, 1)
            if cur == b:
                break
            cur = (cur[0] + dx, cur[1] + dy)
        new["selected"] = None
        new["completed"] += 1
        new["moves"] += 1
    return new


def won(state):
    return (state["selected"] is None
